{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies were included if they used an empirical, quantitative design, either randomised or non-randomised, such as RCTs, clinical trials, quasi-experimental studies or cohort studies; involved adolescents (≥ 10 years, according to the World Health Organization [72] definition) and/or adults (≥ 18 years) with AN, BN, BED or OSFED, according to DSM or International Statistical Classification of Diseases and Related Health Problems (ICD) (research) criteria that were valid at the time of diagnosis, or who exceeded validated cut-off values in questionnaires or interviews based on DSM or ICD (research) criteria for AN, BN, BED or OSFED that are explicitly stated to be used as a proxy for full diagnosis. either (a) compared an active psychotherapeutic intervention group (IG) in an outpatient setting with a WLCG or a no-treatment control group, or (b) retrospectively analysed a cohort of patients who ultimately received outpatient psychotherapy. included a waiting period ≥ 4 weeks for the WLCG, no-treatment group or cohort of patients who ultimately received outpatient psychotherapy; reported ED-specific PROs, measured using the Children's Eating Attitudes Test (chEAT) [73], Eating Disorder Examination-Questionnaire (EDEQ) [74] or EDE-Q 6.0 [75], for all study groups separately; and reported these PROs for a minimum of two time points: (1) at or near the time of initial consultation, diagnostic workup, or study enrolment (baseline), and (2) at least once at a subsequent time point (i.e. at intervention start and/or at follow-up).",
      "reason": "Explicitly specifies study designs, settings, follow-up requirements, and participant characteristics for eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Studies were included regardless of publication status. Both peer-reviewed and grey literature were considered. No restrictions were applied regarding publication year or language.",
      "reason": "Clearly states no restrictions on publication status, year, or language for report eligibility."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence found distinguishing exclusion due to outcomes not measured from outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "A within-group random-effects meta-analysis was performed assessing pre-post change scores of the EDE-Q Global Score (primary analysis) and EDE-Q subscales (secondary analyses).",
      "reason": "Specifies synthesis groups as within-group for waitlist conditions, linked to the objective of assessing effects of waiting time."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_28",
      "quote": "We set narrow eligibility criteria for WLCGs in order to mimic a waiting scenario in routine care as closely as possible. For the screening process, however, we had to establish a threshold for how much contact is permissible, which depended heavily on the description. For instance, we accepted medical monitoring, as described by Glisenti et al. [131], as we viewed it as a safety measure solely for ethical reasons (e.g. adverse health outcomes, suicide prevention), but we did not accept regular encouragement to continue waiting and reminders about receiving treatment afterwards, as described by Clyne et al. [174].",
      "reason": "Provides rationales for notable restrictions on eligibility criteria, such as contact permissible during waiting."
    }
  ],
  "confidence": 90
}

